import re
from taf.selenium.sc.facade import Sc


class SupportedSc(object):
    sc = Sc


class Provider(object):
    @classmethod
    def provide(cls, version=None):
        regex_for_verison = "(?:[Ss][Cc])?(.*)?"
        if version == "" or version is None:
            supported_sc = "sc"
        else:
            version_parsed = re.search(regex_for_verison, version).groups()[0]
            supported_sc = "sc{version}".format(version=version_parsed.lower())

        sc_cls = getattr(SupportedSc, supported_sc, SupportedSc.sc)
        return sc_cls
